/**
 * supabase/functions/_shared/fallbackLogo.ts
 *
 * IMPROVEMENT-PLAN — org-branded PDF fallback (see pdfBranding.ts's
 * embedLogo). Orgs that haven't uploaded a logo_url were shipping reports
 * and invoices with blank header space where their identity should be —
 * this is that gap's fix.
 *
 * There is no dedicated vector brand-mark component in this repo yet
 * (apps/web/assets/logo.png is the only brand asset that exists). This is
 * that PNG, base64-embedded directly in source rather than read from disk
 * at runtime: Edge Functions here have no existing pattern for bundling a
 * local static asset (pdf-lib's fonts are its built-in StandardFonts, and
 * the real org logo is always fetched from Storage at request time, never
 * from a local file) — base64-in-source needs no deploy-config changes and
 * behaves identically to a fetched asset once decoded.
 *
 * TODO: swap this for a dedicated vector Dala brand mark (transparent
 * background, square-ish crop) if/when one exists — this PNG is a 2:1
 * lockup with a baked-in white background, which reads fine on the white
 * PDF pages this app produces today but wouldn't survive a colored page
 * background unchanged.
 */
export const FALLBACK_LOGO_CONTENT_TYPE = 'image/png';

export const FALLBACK_LOGO_BASE64 =
  '';
